                                        !isCarouselPromoActive && artisteFestivalSlide === 1
                                            ? 'bg-neon-red text-white shadow-[0_0_12px_rgba(255,0,51,0.5)]'
                                            : 'bg-white/5 text-gray-400 hover:text-white hover:bg-white/10'
