                                                !isCarouselPromoActive && editorialSlide === sNum
                                                    ? 'bg-[#00ff66] text-black shadow-[0_0_12px_rgba(0,255,102,0.6)]'
                                                    : 'bg-white/5 text-gray-400 hover:text-white hover:bg-white/10'
